        <p class="muted"><a href="{{ game.video_url }}" target="_blank" rel="noopener">Открыть видео отдельно</a></p>
      </section>
    {% endif %}

    {# Места под блоки следующих срезов: добавляются содержимым, без переверстки. #}
    <section id="review-summaries" data-block="T-31"></section>
    <section id="similar-games" data-block="T-34"></section>
    <section id="letsplay" data-block="T-46"></section>

    <p class="muted back"><a href="/games">← ко всем играм</a></p>
  </article>

  <style>
    .game .head { display:flex; gap:24px; flex-wrap:wrap; }
    .game .cover { flex:0 0 226px; aspect-ratio:226/332; background:var(--line);
