    .game .cover img { width:100%; height:100%; object-fit:cover; display:block; }
    .cover-empty { display:flex; height:100%; align-items:center; justify-content:center; font-size:13px; }
    .game .meta { flex:1 1 380px; min-width:0; }
    .game h1 { margin:0 0 12px; font-size:26px; line-height:1.2; }
    .game h2 { font-size:16px; margin:28px 0 10px; }
    .facts { display:grid; grid-template-columns:max-content 1fr; gap:4px 14px; margin:0 0 16px; font-size:14px; }
    .facts dt { color:var(--muted); }
    .facts dd { margin:0; }
    .description { margin:0; white-space:pre-line; }
    table.platforms { border-collapse:collapse; width:100%; font-size:14px; }
    table.platforms th, table.platforms td { text-align:left; padding:8px 10px; border-bottom:1px solid var(--line); }
    table.platforms th { color:var(--muted); font-weight:500; }
    table.platforms tr.lead td:first-child { font-weight:600; }
    .tag { font-size:12px; margin-left:6px; }
    .count { font-size:12px; margin-left:6px; }
    .score { display:inline-block; min-width:30px; padding:2px 6px; border-radius:5px;
             font-weight:600; text-align:center; color:#111; }
    .metascore { background:#ffcc33; }
    .userscore { background:#7ec8a0; }
    .video { position:relative; aspect-ratio:16/9; max-width:720px; background:#000; border-radius:10px; overflow:hidden; }
    .video iframe { position:absolute; inset:0; width:100%; height:100%; border:0; }
    .back { margin-top:32px; }
  </style>
{% endblock %}

